// Color by era
function eraColor(ym) {
  const yr = parseInt(ym.split('-')[0]);
  if (yr < 1974) return '#4472c4';
  if (yr < 1986) return '#ed7d31';
  if (yr < 2003) return '#70ad47';
  if (yr < 2015) return '#c8873a';
  if (yr < 2020) return '#9e6aad';
  return '#e05252';
}

