const momChanges = [];
const momColors = [];
for (let i = 1; i < allData.length; i++) {
  const pct = ((allData[i].p - allData[i-1].p) / allData[i-1].p) * 100;
  momChanges.push(parseFloat(pct.toFixed(2)));
  momColors.push(pct >= 0 ? 'rgba(30,122,74,0.6)' : 'rgba(168,32,32,0.6)');
}

const momCtx = document.getElementById('momChart').getContext('2d');
new Chart(momCtx, {
