  options: {
    responsive: true,
    plugins: {
      legend: { display: false },
      tooltip: {
        callbacks: {
          title: items => items[0].label,
          label: item => ` ${item.raw > 0 ? '+' : ''}${item.raw.toFixed(1)}%`
        }
      }
    },
    scales: {
      x: {
        ticks: {
          maxTicksLimit: 15,
          callback: function(val, idx) {
            const lbl = labels.slice(1)[idx];
