            if (lbl && lbl.endsWith('-01') && parseInt(lbl.split('-')[0]) % 5 === 0) return lbl.split('-')[0];
            return '';
          },
          color: '#5a6478', font: { size: 10 }
        },
        grid: { display: false }
      },
